// GetGlyphInfo returns GlyphInfo for a character or macro.
func GetGlyphInfo(sym string) (GlyphInfo, bool) {
	if info, ok := CMFont[sym]; ok {
		return info, true
	}
	return GlyphInfo{}, false
}
